  /** Every `var(--name[, fallback])` read of exactly `name` (not a longer name), as written. */
  readsOf(name: string): string[];
  /** Colour literals (`#hex`, `rgb(a)(`, `hsl(a)(`) in declaration values of rules that are not token blocks. */
  literalsOutsideTokenBlocks(): string[];
}

export function readStylesheet(text: string, options: StylesheetOptions): Stylesheet;
```

- 實作：`document.createElement("style")` 注入、走訪 `sheet.cssRules`、立刻 `remove()`；`declarations` 由 `style.length` / `style[i]` / `getPropertyValue` / `getPropertyPriority` 列出。不得依賴 regex 去註解。
- `literalsOutsideTokenBlocks` 與舊法的差異（舊法掃整段 `outside` 文字，含 selector；新法只掃 declaration value）在 doc 說明；對 `default.css` 與 board CSS 兩者今天的答案都是 `[]`。
- `stylesheet.test.ts`：用 fixture CSS（含註解、`@media` 巢狀、`@keyframes`、`!important`、兩個 selector 的逗號、同名 class 前綴）覆蓋每個方法，先紅後綠；另對真的 `default.css` 斷言 `rootTokens().size === 30`、`rules.length === 124`（spike 量測的數字，模組可信的證據）。

## Design contract（T2 / T3）

- T2：`default.test.ts` 頂部改 `const TEST_FILE_URL = import.meta.url; const theme = readStylesheet(readBeside(TEST_FILE_URL, "./default.css"), { tokenPrefix: "--siren-", rootSelector: ":root" })`；`themeRules` 刪除；六處 class regex → `theme.selectsClass(name)`；`rules` / `tokenBlocks` / declared / outside / dangling → 模組方法；`ruleBody(s)` → `theme.rule(s)?.cssText ?? ""`；`:root` regex → `theme.tokenBlocks()[0]` / `rootTokens()`；`var(--siren-edge-march…)` 讀法 → `readsOf("--siren-edge-march")`；`cssRulesDeclaring` → `theme.rulesDeclaring`；dark theme → `readStylesheet(readBeside(TEST_FILE_URL, "../../../../demos/theme-dark.css"), …).declaredTokens()`；`renderThemedSVG` 注入 `theme.text`。`readme-tokens.test.ts`：`readText` → `readBeside`、`rootTokens(css)` → 模組（fixture 測試仍在）。`paint-tokens.test.ts`：`readText` → `readBeside`，其餘不動。
